CREATE OR REPLACE FUNCTION outbox.event_uuid(p_ms bigint,p_order bigint) RETURNS uuid
LANGUAGE sql IMMUTABLE STRICT AS $$
  SELECT (
    substr(lpad(to_hex(p_ms),12,'0'),1,8) || '-' ||
    substr(lpad(to_hex(p_ms),12,'0'),9,4) || '-' ||
    '7' || lpad(to_hex(p_order >> 62),3,'0') || '-' ||
    substr('89ab',((p_order >> 60) & 3)::integer + 1,1) ||
    substr(lpad(to_hex(p_order & 1152921504606846975),15,'0'),1,3) || '-' ||
    substr(lpad(to_hex(p_order & 1152921504606846975),15,'0'),4,12)
  )::uuid;
$$;

CREATE OR REPLACE FUNCTION outbox.guard_app_attempt_completion() RETURNS trigger
LANGUAGE plpgsql SECURITY INVOKER
SET search_path = pg_catalog,outbox
AS $$
BEGIN
  IF current_user = 'role_app_backend' THEN
    IF OLD.result IS DISTINCT FROM 'CLAIMED'
       OR OLD.completed_at IS NOT NULL
       OR NEW.result NOT IN ('SENT','ERROR')
       OR NEW.completed_at IS NULL
       OR NEW.tenant_id IS DISTINCT FROM OLD.tenant_id
       OR NEW.event_id IS DISTINCT FROM OLD.event_id
       OR NEW.attempt_ordinal IS DISTINCT FROM OLD.attempt_ordinal
       OR NEW.legacy_message_id IS DISTINCT FROM OLD.legacy_message_id
       OR NEW.legacy_state IS DISTINCT FROM OLD.legacy_state THEN
      RAISE EXCEPTION 'completed or legacy attempt evidence is immutable to "role_app_backend"'
        USING ERRCODE = '42501';
    END IF;
  END IF;
  RETURN NEW;
END $$;

DROP TRIGGER IF EXISTS guard_app_attempt_completion ON outbox.event_attempts;
CREATE TRIGGER guard_app_attempt_completion
BEFORE UPDATE ON outbox.event_attempts
FOR EACH ROW EXECUTE FUNCTION outbox.guard_app_attempt_completion();

CREATE OR REPLACE FUNCTION outbox.guard_app_attempt_completion() RETURNS trigger
LANGUAGE plpgsql SECURITY INVOKER
SET search_path = pg_catalog,outbox
AS $$
DECLARE
  table_owner oid;
  acting_role oid;
BEGIN
  SELECT c.relowner INTO table_owner FROM pg_catalog.pg_class c WHERE c.oid = TG_RELID;
  SELECT r.oid INTO acting_role FROM pg_catalog.pg_roles r WHERE r.rolname = current_user;
  IF acting_role IS DISTINCT FROM table_owner THEN
    IF OLD.result IS DISTINCT FROM 'CLAIMED'
       OR OLD.completed_at IS NOT NULL
       OR NEW.result NOT IN ('SENT','ERROR')
       OR NEW.completed_at IS NULL
       OR NEW.tenant_id IS DISTINCT FROM OLD.tenant_id
       OR NEW.event_id IS DISTINCT FROM OLD.event_id
       OR NEW.attempt_ordinal IS DISTINCT FROM OLD.attempt_ordinal
       OR NEW.legacy_message_id IS DISTINCT FROM OLD.legacy_message_id
       OR NEW.legacy_state IS DISTINCT FROM OLD.legacy_state THEN
      RAISE EXCEPTION 'completed or legacy attempt evidence is immutable outside the table owner'
        USING ERRCODE = '42501';
    END IF;
  END IF;
  RETURN NEW;
END $$;

